@push('scripts')<script>
AppPage.ready(()=>{
const materials=@json($materialData),lots=@json($lotData),steps=[...document.querySelectorAll('.mfg-step')],panels=[...document.querySelectorAll('.wizard-panel')],product=document.getElementById('product_id'),locationInput=document.getElementById('location_id'),qty=document.getElementById('quantity'),materialBox=document.getElementById('material-lines'),expenses=document.getElementById('expense-lines');let materialIndex=0,expenseIndex=0;
const productSearch=document.getElementById('product-search'),productResults=document.getElementById('product-results'),productOptions=[...product.options].filter(o=>o.value);let productActive=-1;
const money=n=>'Rs '+Number(n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function renderProductResults(){const term=productSearch.value.trim().toLowerCase(),location=locationInput.value,matches=productOptions.filter(o=>o.dataset.locations.split(',').includes(location)&&(!term||(o.textContent+' '+(o.dataset.name||'')).toLowerCase().includes(term)));productResults.innerHTML='';productActive=-1;if(!matches.length){productResults.innerHTML='<div class="mfg-product-empty">No products are assigned to this warehouse.</div>'}else matches.forEach(o=>{const button=document.createElement('button');button.type='button';button.className='mfg-product-option';button.textContent=o.textContent.trim();button.onclick=()=>selectProduct(o);productResults.append(button)});productResults.hidden=false;productSearch.setAttribute('aria-expanded','true')}
function selectProduct(option){product.value=option.value;productSearch.value=option.textContent.trim();productResults.hidden=true;productSearch.setAttribute('aria-expanded','false');product.dispatchEvent(new Event('change'))}
function moveProduct(delta){const buttons=[...productResults.querySelectorAll('.mfg-product-option')];if(!buttons.length)return;productActive=(productActive+delta+buttons.length)%buttons.length;buttons.forEach((button,index)=>button.classList.toggle('active',index===productActive));buttons[productActive].scrollIntoView({block:'nearest'})}
productSearch.addEventListener('focus',renderProductResults);productSearch.addEventListener('input',()=>{product.value='';renderProductResults()});productSearch.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();moveProduct(1)}else if(event.key==='ArrowUp'){event.preventDefault();moveProduct(-1)}else if(event.key==='Enter'&&productActive>=0){event.preventDefault();productResults.querySelectorAll('.mfg-product-option')[productActive].click()}else if(event.key==='Escape'){productResults.hidden=true;productSearch.setAttribute('aria-expanded','false')}});document.addEventListener('click',event=>{if(!event.target.closest('.mfg-product-search')){productResults.hidden=true;productSearch.setAttribute('aria-expanded','false')}});
function materialRows(){return [...materialBox.querySelectorAll('.material-row')].map(row=>{const selected=materials.find(item=>item.id==row.querySelector('.material-product').value),variant=selected?.variants.find(item=>item.id==row.querySelector('.material-variant').value),perUnit=+row.querySelector('.material-quantity').value||0,required=perUnit*(+qty.value||0),unitCost=variant?.unit_cost??selected?.unit_cost??0;return{name:selected?.name||'',variant:variant?.label||'',unit:selected?.unit||'',perUnit,required,total:required*unitCost}})}
function refreshMaterials(){const rows=materialRows(),productionQty=+qty.value||0;[...materialBox.querySelectorAll('.material-row')].forEach((row,index)=>{const item=rows[index];row.querySelector('.material-number').textContent=index+1;row.querySelector('.material-total').innerHTML=`<span>${item.required.toLocaleString(undefined,{maximumFractionDigits:4})} ${item.unit}</span><small class="ml-auto text-slate-500">${money(item.total)}</small>`});const cost=rows.reduce((sum,item)=>sum+item.total,0);document.getElementById('material-summary').innerHTML=`<div class="mfg-summary-item"><small>Production quantity</small><b>${productionQty.toLocaleString()} unit(s)</b></div><div class="mfg-summary-item"><small>Raw materials</small><b>${rows.filter(item=>item.name).length} item(s)</b></div><div class="mfg-summary-item"><small>Estimated material cost</small><b>${money(cost)}</b></div>`}
function addMaterial(value={}){const row=document.getElementById('material-template').content.firstElementChild.cloneNode(true),index=materialIndex++,productInput=row.querySelector('.material-product'),variantInput=row.querySelector('.material-variant'),variantWrap=row.querySelector('.variant-wrap'),lotSelect=row.querySelector('.material-lot-select'),lotInput=row.querySelector('.material-lot-manual'),lotStatus=row.querySelector('.material-lot-status'),quantityInput=row.querySelector('.material-quantity');productInput.name=`components[${index}][product_id]`;variantInput.name=`components[${index}][product_variant_id]`;lotInput.name=`components[${index}][source_lot_number]`;quantityInput.name=`components[${index}][quantity_per_unit]`;function syncLotValue(){const manual=lotSelect.value==='__manual__';lotInput.hidden=!manual;if(manual){lotInput.value='';lotInput.focus()}else lotInput.value=lotSelect.value}lotSelect.onchange=syncLotValue;function syncLots(preferred=''){const selectedProduct=productInput.value,selectedLocation=locationInput.value,selectedVariant=variantInput.value,matches=lots.filter(lot=>lot.product_id==selectedProduct&&lot.location_id==selectedLocation&&(!selectedVariant||lot.product_variant_id==selectedVariant));lotSelect.innerHTML='';if(!selectedProduct||!selectedLocation){lotSelect.add(new Option(!selectedLocation?'Select warehouse first':'Select raw material first',''));lotSelect.disabled=true;lotStatus.textContent=!selectedLocation?'Select a production warehouse to load lots.':'Select a raw material to load its lots.';lotStatus.classList.remove('available')}else{lotSelect.add(new Option(matches.length?'Select available lot':'No available lots',''));matches.forEach(lot=>lotSelect.add(new Option(`${lot.lot_number} — available ${Number(lot.available).toLocaleString()}`,lot.lot_number)));lotSelect.add(new Option('Enter lot/reference manually…','__manual__'));lotSelect.disabled=false;lotStatus.textContent=matches.length?`${matches.length} available lot${matches.length===1?'':'s'} in this warehouse.`:'No positive-stock lot found in this warehouse.';lotStatus.classList.toggle('available',matches.length>0)}if(preferred){const exists=[...lotSelect.options].some(option=>option.value===preferred);lotSelect.value=exists?preferred:'__manual__';lotInput.value=preferred;lotInput.hidden=exists}else if(matches.length===1){lotSelect.value=matches[0].lot_number;lotInput.value=matches[0].lot_number;lotInput.hidden=true}else if(matches.length===0&&selectedProduct&&selectedLocation){lotSelect.value='__manual__';lotInput.value='';lotInput.hidden=false}else{lotInput.value='';lotInput.hidden=true}}function syncVariant(){const item=materials.find(material=>material.id==productInput.value),variable=item?.type==='variable';variantInput.innerHTML='<option value="">Select variation</option>';(item?.variants||[]).forEach(variant=>variantInput.add(new Option(variant.label,variant.id)));variantWrap.hidden=!variable;row.classList.toggle('has-variant',variable);variantInput.disabled=!variable;variantInput.required=variable;if(!variable)variantInput.value='';syncLots();refreshMaterials()}productInput.onchange=syncVariant;variantInput.onchange=()=>{syncLots();refreshMaterials()};quantityInput.oninput=refreshMaterials;row.querySelector('.remove-material').onclick=()=>{row.remove();refreshMaterials()};row.syncLots=syncLots;materialBox.append(row);if(value.product_id){productInput.value=value.product_id;syncVariant();variantInput.value=value.product_variant_id||'';quantityInput.value=value.quantity_per_unit||'';syncLots(value.source_lot_number||'')}else syncVariant();refreshMaterials()}
function addExpense(){const row=document.getElementById('expense-template').content.firstElementChild.cloneNode(true),index=expenseIndex++;row.querySelector('.expense-name').name=`expenses[${index}][name]`;row.querySelector('.expense-amount').name=`expenses[${index}][amount]`;row.querySelector('.remove-row').onclick=()=>row.remove();expenses.append(row)}
function go(step){if(step>1&&(!product.value||!document.getElementById('location_id').value||!(+qty.value>0))){alert('Select the product, warehouse and output quantity first.');return}if(step>2&&materialRows().filter(item=>item.name&&item.perUnit>0).length===0){alert('Add at least one raw material and quantity.');return}steps.forEach(item=>{const active=+item.dataset.step===step;item.classList.toggle('active',active);item.classList.toggle('done',+item.dataset.step<step);item.querySelector('button').setAttribute('aria-current',active?'step':'false')});panels.forEach(panel=>panel.classList.toggle('active',+panel.dataset.panel===step));if(step===2)refreshMaterials();if(step===3)review();document.getElementById('mfg-steps').scrollIntoView({behavior:'smooth',block:'start'})}
function review(){const rows=materialRows(),materialCost=rows.reduce((sum,item)=>sum+item.total,0),expenseCost=[...expenses.querySelectorAll('.expense-amount')].reduce((sum,input)=>sum+(+input.value||0),0),total=materialCost+expenseCost,output=product.selectedOptions[0];document.getElementById('review').innerHTML=`<div class="grid gap-3 rounded-xl bg-purple-50 p-4 md:grid-cols-2"><div><small>Finished product</small><b class="block">${output?.dataset.name||''}</b></div><div><small>Output</small><b class="block">${+qty.value} ${output?.dataset.unit||''}</b></div></div><table class="serial-table mt-4"><thead><tr><th>Raw material</th><th>Per unit</th><th>Total required</th><th>Cost</th></tr></thead><tbody>${rows.map(item=>`<tr><td>${item.name}${item.variant?' · '+item.variant:''}</td><td>${item.perUnit} ${item.unit}</td><td>${item.required} ${item.unit}</td><td>${money(item.total)}</td></tr>`).join('')}</tbody></table><div class="mt-4 rounded-xl bg-slate-900 p-4 text-white"><div class="flex justify-between"><span>Raw materials</span><b>${money(materialCost)}</b></div><div class="flex justify-between"><span>Manufacturing expenses</span><b>${money(expenseCost)}</b></div><div class="mt-2 flex justify-between border-t border-white/20 pt-2"><span>Total / estimated unit cost</span><b>${money(total)} / ${money(total/(+qty.value||1))}</b></div></div>`}
function syncProduct(){const selected=product.selectedOptions[0],serial=selected?.dataset.serial==='1';document.getElementById('selling_price').value=selected?.dataset.selling||0;qty.step=serial?'1':'0.0001';document.getElementById('quantity-help').textContent=serial?'One unique serial number will be required for every finished unit.':''}
steps.forEach(step=>step.querySelector('button').onclick=()=>go(+step.dataset.step));document.querySelectorAll('.next-step').forEach(button=>button.onclick=()=>go(+button.dataset.next));locationInput.onchange=()=>{product.value='';productSearch.value='';productSearch.disabled=!locationInput.value;productSearch.placeholder=locationInput.value?'Search products in this warehouse':'Select warehouse first';materialBox.querySelectorAll('.material-row').forEach(row=>row.syncLots?.())};product.onchange=syncProduct;qty.oninput=refreshMaterials;document.getElementById('add-material').onclick=()=>addMaterial();document.getElementById('add-expense').onclick=addExpense;document.getElementById('mfg-form').onsubmit=()=>{document.getElementById('complete-now').value='1';window.setTimeout(()=>document.getElementById('process-button').disabled=true,0)};addMaterial();addExpense();
});
</script>@endpush
